\begin{tikzpicture}[every node/.style={font=\large}]
\draw[<->] (-3.4,0)--(5.4,0) node[right] {$x$};
\draw[<->] (0,-3.4)--(0,3.4) node[above] {$y$};
\draw[thick,blue,<->,domain=-2.51:4.50,smooth,variable=\x] plot ({\x},{0.13*2*(\x+2)*(\x-1)*(\x-4)});
\fill (-2,0) circle (2pt);
\node[below left] at (-2,0) {$(-2,0)$};
\fill (1,0) circle (2pt);
\node[below left] at (1,0) {$(1,0)$};
\fill (4,0) circle (2pt);
\node[below right] at (4,0) {$(4,0)$};
\fill (0,2.08) circle (2pt);
\node[above right] at (0,2.08) {$(0,16)$};
\end{tikzpicture}
[/tikz]

